import {grade,newAttempt,restoreAttempt} from './quiz-engine.mjs';
import {initExtras,renderExtra} from './extras.js';
import {initSupplement,renderSupplement} from './supplement.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
let data,bank,pages,paris,attempt=null,quizView='setup',active='summary',summarySearch='',countrySearch='',storageOK=true;
const pageState={slides:1,documents:1};
const STORE='wwi-unit-quiz-v1';
try{localStorage.setItem('wwi-test','1');localStorage.removeItem('wwi-test');}catch{storageOK=false;}
function save(){if(storageOK)try{localStorage.setItem(STORE,JSON.stringify(attempt));}catch{storageOK=false;}}
const announce=s=>{$('#live').textContent=s;};
function source(kind,first,last=first,label=null){return `<button class="source-button" data-source="${kind}" data-page="${first}">${esc(label??`${kind==='slides'?'Slides':'PDF pages'} ${first}${last!==first?'–'+last:''}`)} <span aria-hidden="true">↗</span></button>`;}
function heading(kicker,title,description,actions=''){return `<div class="section-top"><div><p class="kicker">${kicker}</p><h2>${title}</h2><p>${description}</p></div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`;}
function renderSummary(){
 $('#panel-summary').innerHTML=`${heading('01 / THE BIG PICTURE','From causes to consequences',`Detailed notes in ${data.sections.length} sections: the original slide summary plus the royal telegrams, Western Front readings, and two Crash Course videos. Explore the new sources in Extra Information.`,`<button class="btn small" data-action="print">Print summary <span aria-hidden="true">↗</span></button>`)}
 <div class="summary-layout"><aside class="toc" aria-label="Summary contents"><p class="toc-label">IN THIS GUIDE</p>${data.sections.map((s,i)=>`<a href="#summary/${s.id}"><span class="num">${pad(i+1)}</span><span>${esc(s.title)}</span></a>`).join('')}<a href="#summary/timeline" class="toc-bottom">Key dates & chronology <span aria-hidden="true">↓</span></a></aside><div>
 <div class="lead-card"><p class="kicker">THE CENTRAL IDEA</p><h3>A European crisis becomes<br>a world war.</h3><p>Long-standing rivalries turned an assassination into a global conflict. Industrial warfare transformed its scale; the peace settlement left competing visions of the future.</p></div>
 <div class="cause-grid" aria-label="MAIN causes"><div class="cause"><span class="letter">M</span><strong>Militarism</strong><p>Arms, readiness & rivalry</p></div><div class="cause"><span class="letter">A</span><strong>Alliances</strong><p>Security & entanglement</p></div><div class="cause"><span class="letter">I</span><strong>Imperialism</strong><p>Territory, trade & power</p></div><div class="cause"><span class="letter">N</span><strong>Nationalism</strong><p>Identity & self-rule</p></div></div>
 <div class="tools-row"><label class="search-wrap"><span class="sr-only">Search summary notes</span><input class="search" id="summary-search" type="search" placeholder="Search notes, terms, or events…" value="${esc(summarySearch)}"></label><button class="btn small ghost" data-action="expand-summary">Expand all</button></div><div id="chapter-list"></div>
 <section id="timeline" class="timeline"><p class="kicker">KEEP THE SEQUENCE STRAIGHT</p><h3>Key dates, in context</h3><p class="mini"><a class="source-button" href="#timeline">Explore the full 84-entry timeline →</a></p><div class="timeline-list">${data.timeline.map(([date,title,text])=>`<div class="time-row"><strong>${esc(date)}</strong><div><b>${esc(title)}</b><p>${esc(text)}</p></div></div>`).join('')}</div></section>
 <div class="note">Slide numbers here count from the first WWI title slide. <strong>Slide 1 = PDF page 22.</strong> The original deck’s classroom directions and rosters remain in the Slides tab; they are not treated as new instructions or quiz material.</div></div></div>`;
 renderChapters();
 $('#summary-search').addEventListener('input',e=>{summarySearch=e.target.value;renderChapters();});
}
function renderChapters(){const term=summarySearch.trim().toLowerCase(),matches=data.sections.map((s,i)=>[s,i]).filter(([s])=>JSON.stringify(s).toLowerCase().includes(term));
 $('#chapter-list').innerHTML=matches.length?matches.map(([s,i])=>`<details class="chapter" id="chapter-${s.id}" ${term||i===0?'open':''}><summary><span class="chapter-no">${pad(i+1)}</span><div class="chapter-head"><h3>${esc(s.title)}</h3><p>${esc(s.intro)}</p></div><span class="chapter-chevron" aria-hidden="true">+</span></summary><div class="chapter-content">${s.blocks.map(b=>`<h4>${esc(b.title)}</h4><p>${esc(b.text)}</p>`).join('')}<div class="takeaway"><b>What to remember</b><p>${esc(s.takeaway)}</p></div>${s.note?`<div class="note">${esc(s.note)}</div>`:''}<div class="chapter-source">${s.extraSources?s.extraSources.map(ref=>`<a class="source-button" href="${esc(ref.href)}">${esc(ref.label)} ↗</a>`).join(''):source('slides',...s.slides)+`<button class="source-button" data-study-topic="${topicFor(s.id)}">Quiz this topic →</button>`}</div></div></details>`).join(''):'<div class="empty-search">No matching sections. Try a term such as “alliances,” “trench,” or “Wilson.”</div>';
 const b=$('[data-action="expand-summary"]');if(b)b.textContent=term?'Collapse all':'Expand all';
}
function topicFor(id){return({causes:'Causes',alliances:'Causes',nationalism:'Causes',empire:'Causes',spark:'1914 crisis',fronts:'Warfare',weapons:'Warfare','trench-life':'Trench life','total-war':'Total war',propaganda:'Propaganda','global-war':'Global war','us-entry':'U.S. entry',ending:'War’s end',peace:'Peace settlement'})[id];}
function titleFor(p){return p.title||`${p.section==='slides'?'Slide':'Document page'} ${p.number}`;}
function renderViewer(kind){const isSlides=kind==='slides',arr=pages.filter(p=>p.section===kind),n=Math.max(1,Math.min(arr.length,pageState[kind])),p=arr[n-1];pageState[kind]=n;
 const html=`<div class="viewer" data-viewer="${kind}"><div class="viewer-toolbar"><label><span class="sr-only">Jump to ${isSlides?'slide':'document page'}</span><select data-jump="${kind}">${arr.map(x=>`<option value="${x.number}" ${x.number===n?'selected':''}>${pad(x.number)} · ${esc(titleFor(x))}</option>`).join('')}</select></label><div class="button-row"><button class="btn small ghost" data-zoom="${kind}" aria-pressed="false">Zoom in</button><a class="btn small ghost" href="assets/${kind==='slides'?'slides':'paris-documents'}.pdf#page=${n}" target="_blank" rel="noopener">Open PDF ↗</a></div></div><div class="viewer-stage ${isSlides?'':'docs'}"><img id="${kind}-page" src="assets/${kind}/${String(n).padStart(3,'0')}.webp" width="${p.width}" height="${p.height}" alt="${isSlides?'Original slide':'Original conference document page'} ${n}: ${esc(titleFor(p))}. Source PDF page ${p.pdfPage}." fetchpriority="high"></div><div class="viewer-footer"><button class="btn small" data-page-step="-1" data-kind="${kind}" ${n===1?'disabled':''}>← Previous</button><span class="viewer-caption" aria-live="polite">${isSlides?'Slide':'Document page'} <strong>${n}</strong> of ${arr.length} <span class="muted">· PDF page ${p.pdfPage}</span></span><button class="btn small" data-page-step="1" data-kind="${kind}" ${n===arr.length?'disabled':''}>Next →</button></div><div class="page-strip" aria-label="${isSlides?'Slides':'Document pages'}">${arr.map(x=>`<button data-source="${kind}" data-page="${x.number}" aria-label="${isSlides?'Slide':'Document page'} ${x.number}: ${esc(titleFor(x))}" ${x.number===n?'aria-current="true"':''}>${x.number}</button>`).join('')}</div></div><details class="text-layer"><summary>Extracted text for this page</summary><p class="mini muted" style="margin-top:12px">Verbatim text extracted from the PDF. Text inside images may not appear here; use the original page or PDF for the complete content.</p><pre>${esc(p.text||'This page contains an image or no extractable text. The complete original is shown above.')}</pre></details>`;
 if(isSlides){$('#panel-slides').innerHTML=heading('02 / THE ORIGINAL DECK','Every slide. Just as supplied.','Browse all 127 slide pages in their original order. Images, maps, classroom prompts, and blank pages are preserved.',`<a class="btn small" href="assets/slides.pdf" download="WWI-original-slides.pdf">Download slides ↓</a>`)+html;}else $('#paris-doc-viewer').innerHTML=html;
 const root=isSlides?$('#panel-slides'):$('#paris-doc-viewer');$('[data-jump]',root).addEventListener('change',e=>goSource(kind,Number(e.target.value),true));
 const selected=$('[aria-current=true]',root);if(selected){const strip=selected.parentElement;strip.scrollLeft=selected.offsetLeft-strip.offsetLeft-strip.clientWidth/2;}
}
function renderParis(){
 $('#panel-paris').innerHTML=heading('07 / NEGOTIATING THE PEACE','One conference. Competing futures.','The opening 21 PDF pages contain 17 distinct country and movement perspectives. Compare their motives, then open the original documents.')+`<div class="sub-tabs" role="tablist" aria-label="Paris Peace Conference views"><button role="tab" id="paris-tab-notes" aria-controls="paris-notes" aria-selected="true" data-paris-tab="notes">Motives & summaries</button><button role="tab" id="paris-tab-documents" aria-controls="paris-documents" aria-selected="false" tabindex="-1" data-paris-tab="documents">Original documents <span class="tab-count">21</span></button></div><section id="paris-notes" role="tabpanel" aria-labelledby="paris-tab-notes"><div class="tools-row"><label class="search-wrap"><span class="sr-only">Search conference perspectives</span><input type="search" id="country-search" class="search" placeholder="Find a country, leader, or goal…" value="${esc(countrySearch)}"></label><button class="btn small ghost" data-action="expand-countries">Expand all</button></div><p class="mini muted">Select a perspective to read its motives, tensions, and outcome. Historical clarifications are marked within the notes.</p><div class="country-grid" id="country-grid"></div><section class="comparison"><p class="kicker">COMPARE & CONNECT</p><h3>The main points of friction</h3><table><thead><tr><th scope="col">Issue</th><th scope="col">Competing interests</th></tr></thead><tbody>${paris.comparisons.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></section><div class="note">These notes summarize the assigned viewpoints; the handouts contain role-play language and several historical errors. Clear corrections are marked, and the original documents remain unchanged. The Zionist perspective appears twice in the PDF (pages 16 and 21) and is summarized once here.</div></section><section id="paris-documents" role="tabpanel" aria-labelledby="paris-tab-documents" hidden><div class="section-top"><p>All 21 opening pages, unabridged—including continuation pages and the repeated Zionist sheet.</p><a class="btn small" href="assets/paris-documents.pdf" download="Paris-conference-original-documents.pdf">Download documents ↓</a></div><div id="paris-doc-viewer"></div></section>`;
 renderCountries();$('#country-search').addEventListener('input',e=>{countrySearch=e.target.value;renderCountries();});
}
function renderCountries(){const term=countrySearch.trim().toLowerCase(),arr=paris.perspectives.filter(p=>JSON.stringify(p).toLowerCase().includes(term));$('#country-grid').innerHTML=arr.length?arr.map(p=>`<details class="country" ${term?'open':''}><summary><div class="country-tag"><span>${esc(p.tag)}</span><span aria-hidden="true">+</span></div><h3>${esc(p.name)}</h3><p class="country-leader">${esc(p.leader)}</p><p class="country-goal">${esc(p.goal)}</p></summary><div class="country-body"><h4>Motives & priorities</h4><ul>${p.motives.map(m=>`<li>${esc(m)}</li>`).join('')}</ul><h4>Main tension</h4><p>${esc(p.tension)}</p><h4>Outcome & significance</h4><p>${esc(p.outcome)}</p>${p.note?`<div class="note"><strong>Clarification.</strong> ${esc(p.note)}</div>`:''}${source('documents',p.pages[0],p.pages.at(-1),`Read original · PDF ${p.pages.length>1?'pages '+p.pages.join(' & '):'page '+p.pages[0]}`)}</div></details>`).join(''):'<div class="empty-search">No matching perspectives. Try a country, leader, or “independence.”</div>';}
function setParisTab(name){$$('[data-paris-tab]').forEach(b=>{const on=b.dataset.parisTab===name;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});$('#paris-notes').hidden=name!=='notes';$('#paris-documents').hidden=name!=='documents';if(name==='documents')renderViewer('documents');}
function renderQuizSetup(scope='all'){
 const topics=[...new Set(bank.map(q=>q.topic))];
 $('#panel-quiz').innerHTML=heading('04 / ACTIVE RECALL','Know it. Then prove it.',`${bank.length} questions based only on the slide deck. Each has one best answer, 4–10 choices, an explanation, and a slide reference.`)+`${attempt?`<div class="resume"><p><strong>${attempt.finished?'Your last session is ready to review.':'You have a session in progress.'}</strong><br>${grade(bank,attempt.ids,attempt.responses).answered} of ${attempt.ids.length} questions answered${storageOK?' · Saved on this browser':''}.</p><div class="button-row"><button class="btn primary small" data-action="resume">${attempt.finished?'View results':'Resume session'} →</button></div></div>`:''}<div class="quiz-intro-grid"><form class="quiz-config" id="quiz-config"><h3>Build your study session</h3><label class="field"><span>Choose your coverage</span><select id="quiz-scope"><option value="all">All slide topics · ${bank.length} questions</option><optgroup label="One topic">${topics.map(t=>`<option value="${esc(t)}">${esc(t)} · ${bank.filter(q=>q.topic===t).length}</option>`).join('')}</optgroup></select></label><label class="field"><span>Session length</span><select id="quiz-size"><option value="all">All questions in this selection</option><option value="10">10 questions</option><option value="25">25 questions</option><option value="50">50 questions</option></select></label><label class="check-field"><input type="checkbox" id="quiz-shuffle" checked> Shuffle the question order</label><p class="mini muted" id="quiz-count"></p><button class="btn primary" type="submit">${attempt?'Start a new session':'Start studying'} →</button>${attempt?'<p class="mini muted" style="margin:14px 0 0">Starting a new session replaces the saved session.</p>':''}</form><aside class="quiz-description"><p class="kicker">MORE THAN RECALL</p><h3>Learn from every answer.</h3><p>Work through the full bank or focus on one topic. Check each answer when you’re ready; explanations help you understand the distinction that matters.</p><ul><li>Questions on facts, causes, comparisons, and source interpretation.</li><li>Answer choices are reordered for every new session.</li><li>Review missed and unanswered questions after finishing.</li><li>${storageOK?'Progress stays on this browser, so you can return later.':'Browser storage is unavailable. Your progress will last until this page is closed or refreshed.'}</li></ul><div class="topic-chips">${topics.map(t=>`<span>${esc(t)}</span>`).join('')}</div></aside></div>`;
 $('#quiz-scope').value=scope;updateQuizCount();$('#quiz-scope').addEventListener('change',updateQuizCount);$('#quiz-size').addEventListener('change',updateQuizCount);$('#quiz-config').addEventListener('submit',e=>{e.preventDefault();attempt=newAttempt(bank,{scope:$('#quiz-scope').value,size:$('#quiz-size').value,randomize:$('#quiz-shuffle').checked});quizView='active';save();renderQuizQuestion();scrollMain();});
}
function updateQuizCount(){const s=$('#quiz-scope').value,n=bank.filter(q=>s==='all'||s==='slides'&&q.source.kind==='slides'||q.topic===s).length;const size=$('#quiz-size').value;$('#quiz-count').textContent=`${size==='all'?n:Math.min(n,+size)} questions in this session.`;}
function renderQuizQuestion(){
 if(!attempt){quizView='setup';renderQuizSetup();return;}if(attempt.finished){renderResults();return;}
 const q=bank.find(q=>q.id===attempt.ids[attempt.current]),g=grade(bank,attempt.ids,attempt.responses),checked=Number.isInteger(attempt.responses[q.id]),selected=checked?attempt.responses[q.id]:attempt.drafts[q.id],right=selected===q.answer;
 $('#panel-quiz').innerHTML=`<div class="quiz-shell"><div class="quiz-meta"><span>QUESTION <strong>${attempt.current+1}</strong> / ${attempt.ids.length}</span><span>${g.answered} checked · ${g.correct} correct</span><button class="source-button" data-action="quiz-setup">Session settings</button></div><div class="quiz-progress" role="progressbar" aria-label="Questions checked" aria-valuemin="0" aria-valuemax="${g.total}" aria-valuenow="${g.answered}"><span style="width:${g.answered/g.total*100}%"></span></div><article class="question-card"><p class="question-topic">${esc(q.topic)} <span class="muted">/ ${q.source.kind==='slides'?'SLIDES':'CONFERENCE DOCUMENTS'}</span><h2 id="question-title" tabindex="-1">${esc(q.stem)}</h2><p class="question-instruction">Choose the single best answer · ${q.options.length} options</p><fieldset class="options" aria-labelledby="question-title"><legend class="sr-only">Answer choices</legend>${attempt.orders[q.id].map((index,i)=>`<label class="option ${selected===index?'selected':''} ${checked&&index===q.answer?'correct':''} ${checked&&selected===index&&!right?'incorrect':''}"><input type="radio" name="answer" value="${index}" ${selected===index?'checked':''} ${checked?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span class="option-text">${esc(q.options[index])}</span>${checked&&(index===q.answer||selected===index)?`<span class="option-result">${index===q.answer?'✓ Correct':'× Your answer'}</span>`:''}</label>`).join('')}</fieldset>${checked?`<div class="feedback ${right?'':'wrong'}" role="status"><h3>${right?'✓ Correct.':'Not quite. Here’s the distinction.'}</h3>${!right?`<p><strong>Best answer:</strong> ${esc(q.options[q.answer])}</p>`:''}<p>${esc(q.explanation)}</p>${source(q.source.kind,q.source.first,q.source.last,'Revisit the source')}</div>`:''}<div class="quiz-actions"><button class="btn ghost" data-action="previous-question" ${attempt.current===0?'disabled':''}>← Back</button><div class="button-row">${!checked?`<button class="btn primary" data-action="check" ${selected===undefined?'disabled':''}>Check answer</button>`:''}${attempt.current<attempt.ids.length-1?`<button class="btn ${checked?'primary':''}" data-action="next-question">${checked?'Next question':'Skip for now'} →</button>`:`<button class="btn ${checked?'primary':''}" data-action="finish">See results →</button>`}</div></div></article><div class="quiz-bottom"><span class="mini muted">${storageOK?'Progress is saved on this browser.':'Progress is available for this visit only.'}</span><button class="source-button" data-action="finish">Finish session${g.unanswered?` · ${g.unanswered} unanswered`:''}</button></div><details class="question-map"><summary>Question map · jump to any question</summary><p class="mini muted" style="margin:12px 0 0">✓ Correct · × Incorrect · unmarked = unanswered</p><div class="map-grid">${attempt.ids.map((id,i)=>{const item=bank.find(q=>q.id===id),r=attempt.responses[id],done=Number.isInteger(r),ok=r===item.answer;return `<button data-question-index="${i}" class="${i===attempt.current?'current':''} ${done?(ok?'done-right':'done-wrong'):''}" aria-label="Question ${i+1}, ${done?(ok?'correct':'incorrect'):'unanswered'}" ${i===attempt.current?'aria-current="true"':''}>${i+1}${done?(ok?' ✓':' ×'):''}</button>`;}).join('')}</div></details></div>`;
 $$('input[name=answer]').forEach(el=>el.addEventListener('change',e=>{attempt.drafts[q.id]=Number(e.target.value);save();$$('.option').forEach(l=>l.classList.toggle('selected',Number($('input',l).value)===attempt.drafts[q.id]));$('[data-action=check]').disabled=false;}));
}
function renderResults(){const g=grade(bank,attempt.ids,attempt.responses);quizView='results';$('#panel-quiz').innerHTML=`<div class="quiz-shell"><div class="result-hero"><p class="kicker">SESSION COMPLETE</p><div class="score-number">${g.percent}<span style="font-size:.48em">%</span></div><h2>${g.correct} of ${g.total} correct</h2><p>${g.answered} checked · ${g.answered-g.correct} incorrect · ${g.unanswered} unanswered<br>Unanswered questions count toward the session total.</p><div class="button-row" style="justify-content:center">${g.missed.length?`<button class="btn" data-action="retry-missed">Practice ${g.missed.length} missed / unanswered →</button>`:''}<button class="btn" data-action="quiz-setup">Choose a new session</button></div></div><h3>Your topic breakdown</h3><div class="results-breakdown">${Object.entries(g.topics).map(([t,s])=>`<div class="break-row"><span>${esc(t)}</span><strong>${s.correct} / ${s.total}</strong></div>`).join('')}</div><h3>Review every answer</h3><p class="mini muted">Open a question to see your answer, the best answer, and the explanation.</p>${attempt.ids.map((id,i)=>{const q=bank.find(q=>q.id===id),r=attempt.responses[id],done=Number.isInteger(r),ok=done&&r===q.answer;return `<details class="review-row"><summary><span class="review-status">${ok?'✓ Correct':done?'× Incorrect':'Unanswered'} · ${esc(q.topic)}</span>${i+1}. ${esc(q.stem)}</summary><p><strong>Your answer:</strong> ${done?esc(q.options[r]):'Not answered'}<br><strong>Best answer:</strong> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p>${source(q.source.kind,q.source.first,q.source.last)}</details>`;}).join('')}</div>`;}
function scrollMain(){window.scrollTo({top:$('#main').offsetTop-70,behavior:'instant'});}
function goSource(kind,page,preserveScroll=false){if(preserveScroll){const y=window.scrollY;location.hash=kind==='slides'?`slides/${page}`:`paris/documents/${page}`;requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'instant'}));}else location.hash=kind==='slides'?`slides/${page}`:`paris/documents/${page}`;}
function route(){const bits=location.hash.slice(1).split('/'),next=['summary','slides','readings','quiz','practice','timeline','paris','extra'].includes(bits[0])?bits[0]:'summary';const changed=next!==active;active=next;$$('[data-tab]').forEach(b=>{const on=b.dataset.tab===active;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});$$('[role=tabpanel]').filter(el=>el.id.startsWith('panel-')).forEach(p=>p.hidden=p.id!==`panel-${active}`);
 if(active==='slides'){pageState.slides=Math.max(1,Math.min(127,Math.trunc(Number(bits[1]))||pageState.slides));renderViewer('slides');}
 if(active==='paris'){if(bits[1]==='documents'){pageState.documents=Math.max(1,Math.min(21,Math.trunc(Number(bits[2]))||pageState.documents));setParisTab('documents');}else setParisTab('notes');}
 if(active==='quiz'){if(quizView==='setup')renderQuizSetup();else if(attempt?.finished)renderResults();else renderQuizQuestion();}
 if(changed)scrollMain();
 if(active==='extra')renderSupplement(bits);
 if(['readings','practice','timeline'].includes(active))renderExtra(active,bits);
 if(active==='summary'&&bits[1]){if(summarySearch){summarySearch='';renderSummary();}const el=bits[1]==='timeline'?$('#timeline'):$(`#chapter-${CSS.escape(bits[1])}`);if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({block:'start',behavior:'instant'});}}
 announce(`${({summary:'Summary',slides:'Original slides',readings:'Readings',quiz:'Quiz',practice:'Practice tests',timeline:'Timeline',paris:'Paris Peace Conference',extra:'Extra Information'})[active]} opened.`);
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab){location.hash=b.dataset.tab;return;}
 if(b.dataset.go){location.hash=b.dataset.go;return;}
 if(b.dataset.source){goSource(b.dataset.source,Number(b.dataset.page));return;}
 if(b.dataset.parisTab){location.hash=b.dataset.parisTab==='notes'?'paris':`paris/documents/${pageState.documents}`;return;}
 if(b.dataset.pageStep){goSource(b.dataset.kind,pageState[b.dataset.kind]+Number(b.dataset.pageStep),true);return;}
 if(b.dataset.zoom){const stage=$('.viewer-stage',b.closest('.viewer'));const on=stage.classList.toggle('zoom');b.textContent=on?'Fit to page':'Zoom in';b.setAttribute('aria-pressed',on);return;}
 if(b.dataset.studyTopic){quizView='setup';if(active!=='quiz'){location.hash='quiz';setTimeout(()=>renderQuizSetup(b.dataset.studyTopic),0);}else renderQuizSetup(b.dataset.studyTopic);return;}
 if(b.dataset.questionIndex!==undefined&&attempt){attempt.current=Number(b.dataset.questionIndex);save();renderQuizQuestion();scrollMain();return;}
 switch(b.dataset.action){
 case 'expand-summary':{const all=$$('.chapter'),open=all.some(x=>!x.open);all.forEach(x=>x.open=open);b.textContent=open?'Collapse all':'Expand all';break;}
 case 'expand-countries':{const all=$$('.country'),open=all.some(x=>!x.open);all.forEach(x=>x.open=open);b.textContent=open?'Collapse all':'Expand all';break;}
 case 'print':{summarySearch='';renderSummary();$$('.chapter').forEach(x=>x.open=true);window.print();break;}
 case 'resume':quizView=attempt.finished?'results':'active';attempt.finished?renderResults():renderQuizQuestion();scrollMain();break;
 case 'quiz-setup':quizView='setup';renderQuizSetup();scrollMain();break;
 case 'check':{const q=bank.find(q=>q.id===attempt.ids[attempt.current]);const r=attempt.drafts[q.id];if(Number.isInteger(r)&&attempt.responses[q.id]===undefined){attempt.responses[q.id]=r;save();renderQuizQuestion();announce(r===q.answer?'Correct answer.':'Incorrect answer. Read the explanation.');}break;}
 case 'previous-question':if(attempt.current>0){attempt.current--;save();renderQuizQuestion();scrollMain();}break;
 case 'next-question':if(attempt.current<attempt.ids.length-1){attempt.current++;save();renderQuizQuestion();scrollMain();}break;
 case 'finish':attempt.finished=true;save();renderResults();scrollMain();break;
 case 'retry-missed':{const ids=grade(bank,attempt.ids,attempt.responses).missed;attempt=newAttempt(bank,{ids,randomize:true});quizView='active';save();renderQuizQuestion();scrollMain();break;}
 }
});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const tabs=$$('[role=tab]',tab.parentElement);let idx=tabs.indexOf(tab);idx=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[idx].focus();tabs[idx].click();return;}if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)||e.altKey||e.ctrlKey||e.metaKey)return;const kind=active==='slides'?'slides':active==='paris'&&!$('#paris-documents').hidden?'documents':null;if(kind&&['ArrowLeft','ArrowRight'].includes(e.key)){const n=pageState[kind]+(e.key==='ArrowRight'?1:-1);if(n>=1&&n<=(kind==='slides'?127:21)){e.preventDefault();goSource(kind,n,true);}}});
window.addEventListener('hashchange',()=>{if(data)route();});
try{[data,bank,pages,paris]=await Promise.all(['summary.json','quiz.json','assets/page-index.json','paris.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw new Error(`Could not load ${p}`);return r.json();}));if(storageOK){try{const stored=JSON.parse(localStorage.getItem(STORE));attempt=restoreAttempt(stored,bank);if(attempt)save();}catch{}}await initExtras();data.sections.push(...await initSupplement());renderSummary();renderParis();renderQuizSetup();$('#loading').hidden=true;route();}catch(error){$('#loading').innerHTML=`<p>The study guide could not load all its files. Please refresh the page.</p><button class="btn" onclick="location.reload()">Reload guide</button>`;console.error(error);}
